func metadataToContext(ctx context.Context, md metadata.MD) context.Context {
	if ip := grpcClientIP(ctx); ip != "" {
		ctx = contexts.WithClientIP(ctx, ip)
	}
	if locale := metadataFirstValue(md, "x-locale", "locale", "accept-language"); len(locale) > 0 {
		ctx = localemw.WithLocale(ctx, locale)
	}

	if sessionID := metadataFirstValue(md, "x-session-key", "session-key", "session_key"); len(sessionID) > 0 {
		ctx = session.WithToken(ctx, sessionID)
	}

	return ctx
}

func grpcClientIP(ctx context.Context) string {
	client, ok := peer.FromContext(ctx)
	if !ok || client.Addr == nil {
		return ""
	}
	host, _, err := net.SplitHostPort(client.Addr.String())
	if err == nil {
		return host
	}
	return client.Addr.String()
}

func metadataFirstValue(md metadata.MD, keys ...string) string {
	for _, key := range keys {
		for _, value := range md.Get(key) {
			if value = strings.TrimSpace(value); len(value) > 0 {
				return value
			}
		}
	}
	return ""
}
